#include <utility>
#include <vector>

void selectionSort(std::vector<int>& values)
{
    for (std::size_t i{ 0 }; i + 1 < values.size(); ++i)
    {
        std::size_t smallest{ i };
        for (std::size_t j{ i + 1 }; j < values.size(); ++j)
        {
            if (values[j] < values[smallest])
            {
                smallest = j;
            }
        }
        std::swap(values[i], values[smallest]);
    }
}

unitTests:
TEST("sorts") { std::vector<int> v{ 5, 3, 8, 1, 9, 2 }; selectionSort(v); CHECK_EQ(v, (std::vector<int>{ 1, 2, 3, 5, 8, 9 })); }
TEST("duplicates and negatives") { std::vector<int> v{ 3, -1, 3, 0, -1 }; selectionSort(v); CHECK_EQ(v, (std::vector<int>{ -1, -1, 0, 3, 3 })); }
TEST("already sorted, reversed, tiny") { std::vector<int> a{ 1, 2, 3 }; selectionSort(a); CHECK_EQ(a, (std::vector<int>{ 1, 2, 3 })); std::vector<int> b{ 3, 2, 1 }; selectionSort(b); CHECK_EQ(b, (std::vector<int>{ 1, 2, 3 })); std::vector<int> c{}; selectionSort(c); CHECK(c.empty()); }

